```c++
template <typename T>
constexpr T add(T a, T b) { return a + b; }

int main() {
  auto result1 = add(5, 10); // Compiled into specialized addition for ints
  auto result2 = add(5.5f, 10.5f); // Compiled into specialized addition for floats
  return 0;
}
```

code_example:
template <typename T, std::size_t N>
struct StaticArray {
    T data[N];
};

int main() {
    StaticArray<int, 5> arr1; 
    StaticArray<double, 10> arr2;
    std::cout << "Size of arr1: " << arraySize(arr1) << std::endl; //Compile time evaluation
    std::cout << "Size of arr2: " << arraySize(arr2) << std::endl; //Compile time evaluation
    return 0;
}
